-- LUNA — Jeu de données DÉMO (persona « Camille », 34 ans)
-- ============================================================================
-- OBJECTIF : peupler un compte de démonstration pour présenter l'app à un client.
-- 90 jours de données (2026-05-12 → 2026-08-09), 3 cycles complets (~28 j), corrélées
-- au cycle menstruel ET aux phases lunaires réelles → les écrans Schémas et
-- Rappels affichent de vraies corrélations (humeur×lune, confort×cycle, etc.).
--
-- PRÉREQUIS : créer d'abord l'utilisateur démo (voir README_DEMO.md), puis
-- coller CE fichier dans Supabase > SQL Editor > Run.
--
-- ⚠️ L'e-mail ci-dessous DOIT correspondre à celui du compte démo créé.
--    Le script est IDEMPOTENT : il purge les données de ce compte puis réinsère.
-- ============================================================================

do $$
declare
  uid uuid;
  demo_email text := 'demo.luna@exemple.fr';  -- <<< adapter si besoin
begin
  select id into uid from auth.users where email = demo_email;
  if uid is null then
    raise exception 'Utilisateur démo introuvable (%). Créez-le d''abord (README_DEMO.md).', demo_email;
  end if;

  -- Purge des données existantes de ce compte (idempotence)
  delete from public.entrees_journal where user_id = uid;
  delete from public.journal_types  where user_id = uid;
  delete from public.moments_jour   where user_id = uid;
  delete from public.nuits          where user_id = uid;
  delete from public.suivi_jour     where user_id = uid;
  delete from public.mesures_corps  where user_id = uid;
  delete from public.rappels_etat   where user_id = uid;
  delete from public.regles         where user_id = uid;

  -- ── Type de journal PERSONNALISÉ (démo de la fonctionnalité) ──────────────

  -- ── Débuts de règles (J1) — 3 cycles complets ────────────────────────────

  -- ── moments_jour (200 lignes) ──────────────────────────────

  -- ── nuits (82 lignes) ───────────────────────────────────────

  -- ── suivi_jour / libido (47 lignes) ─────────────────────────

  -- ── mesures_corps / poids (41 lignes) ─────────────────────

  -- ── entrees_journal (83 lignes) ──────────────────────────

  raise notice 'Démo LUNA : données insérées pour % (uid=%)', demo_email, uid;
end $$;
